def read_channel_dxf(data, tolerance=0.1):
    """Read LINE, planar polylines, 3D polylines, ARC and SPLINE modelspace geometry."""
    import math
    import tempfile
    from pathlib import Path
    import ezdxf
    from ezdxf import path as dxf_path
    from ezdxf.disassemble import recursive_decompose
    if not math.isfinite(tolerance) or tolerance < 0.001:
        raise ValueError('Curve tolerance must be at least 0.001 drawing units.')
    with tempfile.TemporaryDirectory(prefix='HYDROGEOMATICS_channel_dxf_') as temp:
        name = Path(temp) / 'input.dxf'
        name.write_bytes(data)
        doc = ezdxf.readfile(name)
    features, ignored, warnings = [], {}, []
    total_points = 0
    for index, entity in enumerate(recursive_decompose(doc.modelspace())):
        if index > 200000:
            raise ValueError('Drawing has too many entities; export the required river layers to a smaller DXF.')
        kind = entity.dxftype()
        if kind not in ('LINE', 'LWPOLYLINE', 'POLYLINE', 'ARC', 'SPLINE'):
            ignored[kind] = ignored.get(kind, 0) + 1
            continue
        try:
            if kind == 'LINE':
                vertices = [entity.dxf.start, entity.dxf.end]
            elif kind == 'POLYLINE' and entity.is_3d_polyline:
                vertices = list(entity.points())
                if entity.is_closed and vertices:
                    vertices.append(vertices[0])
            else:
                vertices = list(dxf_path.make_path(entity).flattening(distance=tolerance, segments=4))
            points = []
            for point in vertices:
                xy = [float(point.x), float(point.y)]
                if not all(math.isfinite(v) for v in xy):
                    raise ValueError('Non-finite coordinate')
                if not points or math.hypot(xy[0]-points[-1][0], xy[1]-points[-1][1]) > 1e-8:
                    points.append(xy)
            if len(points) < 2:
                continue
            if len(points) > 10000:
                raise ValueError('Line has over 10,000 vertices; simplify it or increase curve tolerance.')
            total_points += len(points)
            if total_points > 250000:
                raise ValueError('Drawing has too many line vertices; export fewer layers.')
            features.append({'id': str(index), 'layer': str(entity.dxf.layer), 'type': kind,
                             'handle': str(entity.dxf.get('handle', '') or ''), 'points': points})
        except Exception as exc:
            if 'Drawing has too many' in str(exc):
                raise
            if len(warnings) < 20:
                warnings.append(f'{kind} on {entity.dxf.layer}: {exc}')
    if not features:
        raise ValueError('No usable river linework found. Export LINE, POLYLINE, LWPOLYLINE, ARC or SPLINE entities.')
    return {'features': features, 'insunits': int(doc.header.get('$INSUNITS', 0)),
            'ignored': ignored, 'warnings': warnings, 'tolerance': tolerance}


def handle_channel_dxf_upload(handler):
    import json
    try:
        size = int(handler.headers.get('Content-Length', '0'))
        if size <= 0 or size > 50 * 1024 * 1024:
            raise ValueError('Select a DXF file smaller than 50 MB.')
        tolerance = float(handler.headers.get('X-Curve-Tolerance', '0.1'))
        payload = read_channel_dxf(handler.rfile.read(size), tolerance)
        status = 200
    except Exception as exc:
        status, payload = 400, {'error': str(exc)}
    body = json.dumps(payload, allow_nan=False).encode('utf-8')
    handler.send_response(status)
    handler.send_header('Content-Type', 'application/json; charset=utf-8')
    handler.send_header('Content-Length', str(len(body)))
    handler.send_header('Cache-Control', 'no-store')
    handler.end_headers()
    handler.wfile.write(body)


class Handler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path != '/api/dxf':
            self.send_error(404)
            return
        handle_channel_dxf_upload(self)

    def do_GET(self):
        if self.path.split("?", 1)[0] not in ("/", "/index.html"):
            self.send_error(404)
            return
        body = APPLICATION_HTML.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, fmt, *args):
        pass


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--no-browser", action="store_true", help="Print URL without opening a browser")
    parser.add_argument("--check", action="store_true", help="Check embedded application without starting server")
    args = parser.parse_args()
    if args.check:
        required = ('id="mapScreen"', 'id="makeMapDesign"', 'function calculate()', 'function volumes(', '</html>')
        if not all(item in APPLICATION_HTML for item in required):
            raise SystemExit("Application bundle is incomplete")
        print("OK: embedded channel design, map and volume application")
        return
    server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
    server.daemon_threads = True
    url = f"http://127.0.0.1:{server.server_address[1]}/"
    print("DREDGE VOLUME is running locally:", url, flush=True)
    print("Keep this terminal open. Press Ctrl+C to stop.", flush=True)
    if not args.no_browser:
        threading.Timer(0.5, webbrowser.open, args=(url,)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopped.")
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
